    /* ---------------- v0.16.9（C3-C / E16+H-8）：资产/场景卡多轮审核（asset-save 写入口） ---------------- */
    const ASSET_REVIEW_STATUS_ORDER = ['draft', 'pending', 'rejected', 'approved', 'final']
    const ASSET_REVIEW_STATUS_LABELS = { draft: 'Draft', pending: 'Pending review', rejected: 'Rejected', approved: 'Approved', final: 'Finalized' }
