    const DIRECTOR_BRIEF_LIMITS = { assetsPerKind: 50, byScene: 20, lightPlan: 10, propsNeeded: 10, risks: 10, notes: 500, shotPurposes: 50, emotionBeats: 12, keyFramesPerScene: 10, compositionPerScene: 12, handoff: 50, summary: 500, handoffBatches: 20 }
