    /** 页内模式器（role=group + aria-pressed；不使用 select/tablist）。 */
    function PageModeTabs(props) {
      const p = props || {}
      const modes = Array.isArray(p.modes) ? p.modes : []
      const value = String(p.value || '')
      return h('div', { className: 'ad-rev-modes', role: 'group', 'aria-label': p.ariaLabel || 'In-page mode' },
        modes.map((mode) => h('button', {
          key: mode.key,
          type: 'button',
          className: 'ad-rev-mode ad-btn ad-sm',
          'aria-pressed': value === mode.key,
          onClick: () => { if (typeof p.onChange === 'function' && value !== mode.key) p.onChange(mode.key) },
        }, mode.label)))
    }

    /** 空态（不使用 emptyState：避免计数红线）。 */
    function RevEmpty(props) {
      const p = props || {}
      return h('div', { className: 'ad-rev-empty', role: 'status' },
        h('div', { className: 'ad-rev-empty-title' }, p.title || 'No data yet'),
        p.desc ? h('div', { className: 'ad-rev-empty-desc' }, p.desc) : null,
        p.next ? h('div', { className: 'ad-rev-hint' }, p.next) : null)
    }

    /** 小徽标（文本 + tone；颜色用现有语义 token）。 */
    function RevChip(props) {
      const p = props || {}
      return h('span', { className: 'ad-rev-chip', 'data-tone': p.tone || 'plain' }, p.children)
    }
    /* v0.16.2（C1-C）：契约页「八大设定（可选）」8 字段（E14 add-only；空串删键/读不补默认）
     * 字段顺序 = worldSpace→worldTime→powerSystem→speciesEcology→factions→resourceEconomy→cultureBelief→soulDeath */
    const CONTRACT_WORLD_FIELDS = [
      ['worldSpace', 'Geography & Space', 1500, 'Stage / travel cost / spatial structure'],
      ['worldTime', 'Time & History', 1500, 'Era / key historical events / time rules'],
      ['powerSystem', 'Power System', 2000, 'Power source / ceiling / cost (state the limit and cost clearly)'],
      ['speciesEcology', 'Species & Ecology', 1200, 'Species / ecology / inter-species relations'],
      ['factions', 'Society & Factions', 1500, 'Power balance / camps / conflicts'],
      ['resourceEconomy', 'Resources & Economy', 1200, 'Scarce resources / currency / exchange rules'],
      ['cultureBelief', 'Culture & Belief', 1500, 'Beliefs / customs / taboos'],
      ['soulDeath', 'Soul / Life & Death / Karma', 1500, 'Afterlife / resurrection / weight of death'],
    ]

    /** 八大字段读取：仅接受 string；缺省/非法类型按未填处理（读不补默认）。 */
    function contractWorldValue(contract, key) {
      const value = contract && typeof contract === 'object' ? contract[key] : undefined
      return typeof value === 'string' ? value : ''
    }

    /** 已填计数（trim 后非空；用于折叠组「已填 X/8 / 未填写」）。 */
    function contractWorldFilledCount(contract) {
      return CONTRACT_WORLD_FIELDS.filter(([key]) => contractWorldValue(contract, key).trim() !== '').length
    }

    /** 保存 payload（Lead 19:2x 修正）：8 个键**始终存在**且为 string —— 未填/清空发 ''，
     *  由宿主 C1-H 在 trim 后删除该键（解决「清空字段无法删除旧值」）；非空发 trim 值；
     *  其余 7 字段与未知旧字段原样保留。 */
    function contractWorldPayload(contract) {
      const payload = contract && typeof contract === 'object' ? { ...contract } : {}
      for (const [key] of CONTRACT_WORLD_FIELDS) {
        const value = contractWorldValue(payload, key).trim()
        payload[key] = value ? value : ''
      }
      return payload
    }

    /** 超长前端提示（trim 后字符数 > 上限）；后端 C1-H 400 仍为最终权威。 */
    function contractWorldOverLimit(contract) {
      return CONTRACT_WORLD_FIELDS
        .map(([key, label, limit]) => [label, contractWorldValue(contract, key).trim().length, limit])
        .filter(([, length, limit]) => length > limit)
    }
    /* ============================================= v0.12.1（task-8）：独立设置页 */
    // 宿主 settings.section（侧栏「设置 → AI 短剧」）与项目页面板内设置浮层共用同一组件：
