          const rawMime = result && typeof result.mime === 'string' ? result.mime.trim() : ''
          const mime = /^[a-z]+\/[a-z0-9.+-]+$/i.test(rawMime) ? rawMime : 'application/octet-stream'
          const base64 = result && typeof result.base64 === 'string' ? result.base64 : ''
