              if (cached && cached.status === 'error') return h('span', { className: 'ad-asset-thumb' }, h('span', { className: 'ad-asset-placeholder' }, 'Failed to read image'))
              return h('span', { className: 'ad-asset-thumb' }, h('span', { className: 'ad-asset-placeholder', 'data-lazy-asset-src': src.value }, 'Loading…'))
