            if (!row || !row.data || styleFrozen) return
            if (typeof window !== 'undefined' && typeof window.confirm === 'function' && !window.confirm('Apply shared style "' + row.data.name + '" to the current draft? This overwrites the unsaved five dimensions/films/directors (reference images unchanged; not saved automatically).')) return
            setStyleDraft(styleDraftOf(row.data.style))
            setStyleReferenceFilms(visualReferenceFilmsOf(row.data.films))
